code.java:
public int strStr(String haystack, String needle) {
    int n = haystack.length(), m = needle.length();
    if (m == 0) {
        return 0;
    }
    int[] lps = new int[m];
    int length = 0, i = 1;
    while (i < m) {
        if (needle.charAt(i) == needle.charAt(length)) {
            lps[i++] = ++length;
        } else if (length > 0) {
            length = lps[length - 1];
        } else {
            lps[i++] = 0;
        }
    }
    int a = 0, j = 0;
    while (a < n) {
        if (haystack.charAt(a) == needle.charAt(j)) {
            a++;
            j++;
            if (j == m) {
                return a - j;
            }
        } else if (j > 0) {
            j = lps[j - 1];
        } else {
            a++;
        }
    }
    return -1;
}

