def strStr(self, haystack: str, needle: str) -> int:
    n, m = len(haystack), len(needle)
    if m == 0:
        return 0
    lps = [0] * m
    length = 0
    i = 1
    while i < m:
        if needle[i] == needle[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length > 0:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    a = j = 0
    while a < n:
        if haystack[a] == needle[j]:
            a += 1
            j += 1
            if j == m:
                return a - j
        elif j > 0:
            j = lps[j - 1]
        else:
            a += 1
    return -1

